$path=Resolve-Path 'outputs/Excel Column Mapper.html'
$script:content=[IO.File]::ReadAllText($path)
function Replace-Section([string]$start,[string]$end,[string]$replacement){$a=$script:content.IndexOf($start);$b=$script:content.IndexOf($end,$a);if($a -lt 0 -or $b -lt 0){throw "Missing section: $start"};$script:content=$script:content.Substring(0,$a)+$replacement+$script:content.Substring($b)}
$script:content=$script:content.Replace("'Email':['email','business email','contact email','e-mail']", "'Email':['email','business email','work email','email address','contact email','e-mail']")
$script:content=$script:content.Replace("'Contact Number':['phone','phone number','mobile','telephone','contact number']", "'Contact Number':['phone','phone number','work phone','mobile number','mobile','telephone','contact number']")
$script:content=$script:content.Replace("'Contact Person *':['contact person','full name','contact name','person']", "'Contact Person *':['contact person','contact','full name','contact name','person','lead name']")
$script:content=$script:content.Replace("'Contact Person':['contact person','name','full name','contact name','person','lead name']", "'Contact Person':['contact person','contact','name','full name','contact name','person','lead name']")
$script:content=$script:content.Replace("'Contact Lead Stage':['lead stage','lead status','status']", "'Contact Lead Stage':['lead stage','lead status','status']")
$mapping=@'
function renderMapping(){let d=datasets.find(x=>x.id===$('#mapPick')?.value);if(!d)return;mappingConfirmed=!!d.confirmed;d.map=d.map||{};d.priority=d.priority||{};for(let h of d.headers)if(!(h in d.map)){let s=suggest(h,d);d.map[h]=s.field;}let unmapped=d.headers.filter(h=>!d.map[h]),ambiguous=d.headers.filter(h=>suggest(h,d).confidence==='Low'&&!d.map[h]),targets=template.fields.filter(f=>d.headers.filter(h=>d.map[h]===f.name).length>1);$('#mappingTable').innerHTML=`${unmapped.length?`<div class="notice validation-warning">Potential data loss: ${unmapped.length} source column(s) are skipped. Review them before confirming.</div>`:''}${ambiguous.length?`<div class="notice validation-warning">${ambiguous.length} ambiguous suggestion(s) need a manual destination choice.</div>`:''}${targets.length?`<div class="notice">Multiple source columns target the same field. Priority controls fallback; conflicting non-empty values will be listed in validation.</div>`:''}<div class="row between" style="margin:12px 0"><span class="small">Review each suggestion and its reason. Priority 1 wins when multiple values map to one field.</span><div class="row"><button id="resetMapping">Reset suggestions</button><button id="confirmMapping" class="primary">${mappingConfirmed?'Mappings confirmed ✓':'Confirm mappings'}</button></div></div><div class="tablewrap scroll"><table class="mapping"><thead><tr><th>Your column</th><th>Maps to</th><th>Priority</th><th>Confidence &amp; reason</th></tr></thead><tbody>${d.headers.map((h,i)=>{let s=suggest(h,d),part=namePart(h),paired=part&&personField()&&d.headers.some(x=>namePart(x)===(part==='first'?'last':'first'));return `<tr><td><b>${esc(h)}</b></td><td><select data-header="${esc(h)}"><option value="">— Skip this column —</option>${paired?`<option value="__COMBINE_CONTACT__" ${d.map[h]==='__COMBINE_CONTACT__'?'selected':''}>Combine name parts → ${esc(personField())}</option>`:''}${template.fields.map(f=>`<option value="${esc(f.name)}" ${d.map[h]===f.name?'selected':''}>${esc(f.name)}${f.required?' *':''}</option>`).join('')}</select></td><td><input data-priority="${esc(h)}" type="number" min="1" value="${Number(d.priority[h]||i+1)}" aria-label="Priority for ${esc(h)}"></td><td><b class="tag ${s.confidence.toLowerCase()}">${esc(s.confidence)}</b><div class="small">${esc(s.reason||'')}</div></td></tr>`}).join('')}</tbody></table></div>`;document.querySelectorAll('[data-header]').forEach(el=>el.onchange=()=>{d.map[el.dataset.header]=el.value;mappingConfirmed=false;d.confirmed=false;renderMapping();});document.querySelectorAll('[data-priority]').forEach(el=>el.onchange=()=>{d.priority[el.dataset.priority]=Math.max(1,+el.value||1);mappingConfirmed=false;d.confirmed=false;});$('#resetMapping').onclick=()=>{d.map={};d.priority={};mappingConfirmed=false;d.confirmed=false;renderMapping();};$('#confirmMapping').onclick=()=>{mappingConfirmed=true;d.confirmed=true;$('#confirmMapping').textContent='Mappings confirmed ✓';};}
'@
Replace-Section 'function renderMapping(){' 'function resolveTarget(d,row,target){' $mapping
$css=@'
.mapping .tag.low{color:#b45309}.mapping .tag.medium{color:#4f6bed}.mapping .tag.high{color:#16815f}.validation-card .scroll{max-height:330px}
'@
$script:content=$script:content.Replace('</style></head>',$css+'</style></head>')
[IO.File]::WriteAllText($path,$script:content,[Text.UTF8Encoding]::new($false))
Write-Output 'Updated mapping reasons, ambiguity warnings and name-combine control.'
